    static func isPrivacyPlaceholderArtifact(_ text: String) -> Bool {
        let normalized = text.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        guard normalized.hasPrefix("<") && normalized.hasSuffix(">") else { return false }
